	flushCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	td.runTransmute(flushCtx, batch)
}

func (td *TableDebouncer) drainRemainingOnStop(firstBatch []NatsMsgTask) {
	// BẮT BUỘC chiếm đủ toàn bộ cap(td.sem) slot trước tiên để đợi mọi mẻ in-flight hoàn tất 100% (B2)
	for i := 0; i < cap(td.sem); i++ {
		td.sem <- struct{}{}
	}
	defer func() {
		for i := 0; i < cap(td.sem); i++ {
			<-td.sem
		}
	}()

	if len(firstBatch) > 0 {
		td.runBatchWithShutdownTimeout(firstBatch)
	}

	// Chờ mọi goroutine vừa gọi takeFlushBatchLocked() hoàn tất enqueueFlushBatch() (0 rơi batch — B2)
	td.mu.Lock()
	for td.enqueuing > 0 {
		td.enqueueCond.Wait()
	}
	td.mu.Unlock()

